import numpy as np


def annual_vol(returns):
    # sample standard deviation, scaled by the square root of 252 days
    return float(np.std(returns, ddof=1) * np.sqrt(252))

def worst_drawdown(prices):
    peak, worst = prices[0], 0.0
    for p in prices:
        peak = max(peak, p)
        worst = max(worst, 1 - p / peak)
    return worst

