#include <algorithm>
#include <cmath>
#include <vector>

double crr_price(double S, double K, double r, double sigma, double T, int n, bool call) {
    const double dt = T / n;
    const double u = std::exp(sigma * std::sqrt(dt));
    const double d = 1.0 / u;
    const double q = (std::exp(r * dt) - d) / (u - d);
    const double disc = std::exp(-r * dt);
    std::vector<double> v(n + 1);
    for (int j = 0; j <= n; ++j) {
        const double s = S * std::pow(u, n - j) * std::pow(d, j);
        v[j] = std::max(call ? s - K : K - s, 0.0);
    }
    for (int step = n; step > 0; --step)
        for (int j = 0; j < step; ++j)
            v[j] = disc * (q * v[j] + (1 - q) * v[j + 1]);   // reuse one vector
    return v[0];
}

